namespace EncDotNet.S100.Testing.Scenarios;

/// <summary>
/// A seeded pseudo-random sequence (SplitMix64) whose output is fixed by this
/// code alone, so a seed gives the same values on every runtime and platform.
/// </summary>
/// <remarks>
/// <see cref="System.Random"/> is not used: its seeded sequence is an
/// implementation detail of the runtime and may change between releases,
/// which would change generated bytes.
/// </remarks>
public sealed class ScenarioRandom
{
    private ulong _state;

    /// <summary>Creates a sequence from <paramref name="seed"/>.</summary>
    /// <param name="seed">The seed.</param>
    public ScenarioRandom(ulong seed) => _state = seed;

    /// <summary>
    /// Creates an independent sequence for one named use, so adding a draw in
    /// one place doesn't shift the values drawn elsewhere.
    /// </summary>
    /// <param name="seed">The scenario seed.</param>
    /// <param name="stream">A stable name for the use, such as <c>"soundings"</c>.</param>
    /// <returns>The sequence.</returns>
    public static ScenarioRandom For(ulong seed, string stream)
    {
        ArgumentNullException.ThrowIfNull(stream);

        // FNV-1a over the stream name's UTF-16 code units, mixed with the seed.
        var hash = 14695981039346656037UL;
        foreach (var c in stream)
        {
            hash = (hash ^ c) * 1099511628211UL;
        }

        return new ScenarioRandom(seed ^ hash);
    }

    /// <summary>The next 64 random bits.</summary>
    /// <returns>The value.</returns>
    public ulong NextUInt64()
    {
        var z = _state += 0x9E3779B97F4A7C15UL;
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
        z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
        return z ^ (z >> 31);
    }

    /// <summary>A value in [0, 1) with 53 random bits.</summary>
    /// <returns>The value.</returns>
    public double NextDouble() => (NextUInt64() >> 11) * (1.0 / (1UL << 53));

    /// <summary>A value in [<paramref name="min"/>, <paramref name="max"/>).</summary>
    /// <param name="min">The lower bound.</param>
    /// <param name="max">The upper bound.</param>
    /// <returns>The value.</returns>
    public double NextDouble(double min, double max) => min + (max - min) * NextDouble();
}
